import Domain
@preconcurrency import FluidAudio
import Foundation
import Logging
import Utilities

// MARK: - FluidDiarizationPlugin

// Error mapping: notInitialized/modelDownloadFailed/modelCompilationFailed → modelNotLoaded,
// all inference errors → inferenceFailed.

/// FluidAudio-backed speaker diarization engine.
///
/// ## Thread Safety
/// All mutable state (`diarizer`) is actor-isolated. No unchecked-Sendable workaround
/// is required.
///
/// `DiarizerManager` is a non-Sendable class and never crosses isolation boundaries.
/// `runDiarization(samples:sampleRate:)` accesses `diarizer` entirely within actor
/// isolation so the non-Sendable reference stays within a single isolation domain at
/// all times.
public actor FluidDiarizationPlugin: DiarizationEngine {
    private let diarizationQueue = DispatchSerialQueue(
        label: "app.the-record.diarization",
        qos: .userInitiated
    )
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        diarizationQueue.asUnownedSerialExecutor()
    }

    // MARK: - Extracted DTO

    /// Primitive fields extracted from `TimedSpeakerSegment` so they can cross actor
    /// isolation boundaries safely without naming the FluidAudio type.
    private struct ExtractedSegment {
        let speakerId: String
        let startTime: Float
        let endTime: Float
        let quality: Float
    }

    // MARK: - Actor State

    private var diarizer: DiarizerManager?
    /// Re-entrancy guard for `diarizer` access. Released only once the detached
    /// inference task backing a `diarize()` call has actually finished — see
    /// `runDetached(timeout:operation:)` — never merely because a timeout race
    /// resolved. This keeps a subsequent `diarize()` call from touching the
    /// shared, non-Sendable `diarizer` while a prior timed-out call's detached
    /// task is still running in the background (#195).
    private var isDiarizing = false
    private let logger = AppLogger.for(category: "Diarization")

    /// Maximum time allowed for a single `performCompleteDiarization` call.
    ///
    /// Default: 120 seconds. Benchmark data: 155× RTF on Apple Silicon means a
    /// typical 30-minute meeting completes in <1 second — 120s is a 120× safety margin.
    /// Pass `.milliseconds(1)` in tests to force a timeout immediately.
    private let inferenceTimeout: Duration

    /// Seam for unit-testing the timeout path without a real DiarizerManager.
    /// `nil` in production — set only via the internal test initializer.
    private let testInferenceFunction: (@Sendable ([Float], Int) async throws -> [SpeakerSegment])?

    // MARK: - Init

    /// - Parameter inferenceTimeout: Per-call timeout for `performCompleteDiarization`.
    ///   Defaults to 120 seconds.
    public init(inferenceTimeout: Duration = TimeoutConfig.diarizationInference) {
        self.inferenceTimeout = inferenceTimeout
        testInferenceFunction = nil
    }

    /// Internal initializer for timeout unit tests. Bypasses DiarizerManager entirely.
    init(
        inferenceTimeout: Duration,
        testInference: @escaping @Sendable ([Float], Int) async throws -> [SpeakerSegment]
    ) {
        self.inferenceTimeout = inferenceTimeout
        testInferenceFunction = testInference
    }

    /// Exposes `inferenceTimeout` for test assertions only.
    var inferenceTimeoutForTesting: Duration {
        inferenceTimeout
    }

    // MARK: - DiarizationEngine

    public func prepare() async throws {
        guard diarizer == nil else {
            logger.info("Diarizer already initialized — skipping")
            return
        }

        logger.info("Downloading FluidAudio diarizer models")
        do {
            let models = try await withTimeout(TimeoutConfig.modelLoad) {
                try await DiarizerModels.downloadIfNeeded()
            }
            let manager = DiarizerManager()
            manager.initialize(models: models)
            diarizer = manager
            logger.info("FluidAudio diarizer ready")
        } catch let error as DiarizerError {
            throw mapError(error)
        } catch {
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
    }

    public func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        guard !samples.isEmpty else {
            throw TranscriptionError.audioTooShort
        }

        guard !isDiarizing else {
            throw TranscriptionError.inferenceFailed(underlying: nil)
        }
        isDiarizing = true

        // Test seam: bypass DiarizerManager when a test inference function is injected.
        // Routed through the same runDetached(timeout:operation:) helper as the real
        // FluidAudio path below so the timeout/cancellation behavior under test matches
        // production exactly. runDetached releases isDiarizing once the detached task
        // truly finishes, not when this call returns, so no defer is needed here.
        if let testFn = testInferenceFunction {
            do {
                return try await runDetached(timeout: inferenceTimeout) {
                    try await testFn(samples, sampleRate)
                }
            } catch {
                throw TranscriptionError.inferenceFailed(underlying: error)
            }
        }

        guard diarizer != nil else {
            // No detached task was spawned for this call, so runDetached never got
            // a chance to release the guard — release it here before throwing.
            isDiarizing = false
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }

        logger.debug("Diarizing \(samples.count, privacy: .private) samples at \(sampleRate, privacy: .public) Hz")

        let extracted: [ExtractedSegment]
        do {
            extracted = try await runDiarization(samples: samples, sampleRate: sampleRate)
        } catch let error as DiarizerError {
            throw mapError(error)
        } catch let error as TranscriptionError {
            throw error
        } catch {
            throw TranscriptionError.inferenceFailed(underlying: error)
        }

        return extracted.map { seg in
            SpeakerSegment(
                speakerId: SpeakerID(seg.speakerId),
                startTime: TimeInterval(seg.startTime),
                endTime: TimeInterval(seg.endTime),
                confidence: Double(seg.quality)
            )
        }
    }

    public func isReady() async -> Bool {
        diarizer != nil
    }

    // MARK: - Private Inference Helper

    /// Calls `performCompleteDiarization` and extracts primitives from the result.
    ///
    /// `DiarizerManager` is a non-Sendable class, so `unsafeManager` is escaped into a
    /// detached task via `nonisolated(unsafe)` for the duration of the call — the
    /// reference briefly leaves actor isolation rather than staying confined to it.
    /// `runDetached(timeout:operation:)` retains the detached task's handle and cancels
    /// it explicitly if the timeout fires; because `performCompleteDiarization` never
    /// checks for cancellation, that cancel request does not stop it — see
    /// `runDetached`'s doc comment for how the `isDiarizing` guard stays correct anyway.
    /// Returns extracted data as domain-safe primitives so callers never need to
    /// name the FluidAudio `TimedSpeakerSegment` type across an isolation boundary.
    private func runDiarization(
        samples: [Float],
        sampleRate: Int
    ) async throws -> [ExtractedSegment] {
        guard let manager = diarizer else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }
        nonisolated(unsafe) let unsafeManager = manager
        let result = try await runDetached(timeout: inferenceTimeout) {
            try unsafeManager.performCompleteDiarization(samples, sampleRate: sampleRate)
        }
        return result.segments.map { seg in
            ExtractedSegment(
                speakerId: seg.speakerId,
                startTime: seg.startTimeSeconds,
                endTime: seg.endTimeSeconds,
                quality: seg.qualityScore
            )
        }
    }

    /// Runs `operation` on a detached task, racing it against `timeout`.
    ///
    /// Unstructured tasks (`Task.detached`) are not children of the calling task, so
    /// cancelling the caller does not automatically cancel them — `withTimeout` alone
    /// leaves a timed-out detached task running as an orphan. This helper retains the
    /// detached task's handle and explicitly calls `task.cancel()` from a
    /// `withTaskCancellationHandler` `onCancel` block when the timeout fires, so
    /// cancellation-aware work inside `operation` (e.g. `Task.sleep`) unwinds promptly
    /// instead of running to completion in the background.
    ///
    /// `performCompleteDiarization` (the real FluidAudio call) is synchronous and
    /// never checks for cancellation, so `task.cancel()` is a no-op on that path — the
    /// detached task keeps running as a genuine orphan after a timeout, and it stays
    /// non-Sendable-unsafe to touch `diarizer` again until that orphan is done. The
    /// task below awaits `task.value` independently of the timeout race above and
    /// releases `isDiarizing` only once the detached work has truly finished, so a
    /// subsequent `diarize()` call can never run concurrently against `diarizer`
    /// while an orphan from a prior timeout is still in flight (#195). Because the
    /// native call cannot actually be interrupted, a sufficiently long native hang
    /// still ties up this instance's single "slot" indefinitely — that residual risk
    /// is expected given `performCompleteDiarization` offers no cancellation hook.
    private func runDetached<T: Sendable>(
        timeout: Duration,
        operation: @escaping @Sendable () async throws -> T
    ) async throws -> T {
        let task = Task.detached(operation: operation)
        Task { [weak self] in
            _ = try? await task.value
            await self?.finishDiarizing()
        }
        return try await withTimeout(timeout) {
            try await withTaskCancellationHandler {
                try await task.value
            } onCancel: {
                task.cancel()
            }
        }
    }

    /// Releases the `isDiarizing` re-entrancy guard. Called only from the
    /// completion-watcher task spawned in `runDetached(timeout:operation:)`, once
    /// the detached inference task it wraps has genuinely finished.
    private func finishDiarizing() {
        isDiarizing = false
    }

    // MARK: - Error Mapping

    private func mapError(_ error: DiarizerError) -> TranscriptionError {
        switch error {
        case .notInitialized, .modelDownloadFailed, .modelCompilationFailed:
            .modelNotLoaded(underlying: error)
        case .embeddingExtractionFailed, .invalidAudioData, .processingFailed,
             .memoryAllocationFailed, .invalidArrayBounds:
            .inferenceFailed(underlying: error)
        }
    }
}

import Alignment
import AudioInfrastructure
import Domain
import Foundation
import MLInfrastructure
import Utilities

enum Quality: String, CaseIterable {
    case fast
    case high
    case max

    var description: String {
        switch self {
        case .fast: "Parakeet only (~275x RTF)"
        case .high: "Parakeet + WhisperKit cleanup (two-pass)"
        case .max: "WhisperKit distil-large-v3 only (highest accuracy)"
        }
    }
}

struct PipelineResult {
    let audioSeconds: Double
    let quality: Quality
    let transcription: TranscriptionSegment
    let transcriptionTime: TimeInterval
    let cleanupTranscription: TranscriptionSegment?
    let cleanupTime: TimeInterval?
    let speakerSegments: [SpeakerSegment]
    let diarizedSegments: [DiarizedSegment]
    let diarizationTime: TimeInterval
    let summary: MeetingSummary?
    let summaryTime: TimeInterval?
    let promptTokens: Int?
    let contextWindow: Int?
    let totalTime: TimeInterval
}

actor PipelineRunner {
    private let parakeet: ParakeetPlugin
    private let whisper: WhisperKitPlugin
    private let diarizer: FluidDiarizationPlugin
    private let xgrammarSummarizer: XGrammarSummarizationPlugin
    private let loader: AudioFileLoader
    private let telemetry: InferenceTelemetry

    init() {
        parakeet = ParakeetPlugin()
        whisper = WhisperKitPlugin()
        diarizer = FluidDiarizationPlugin()
        xgrammarSummarizer = XGrammarSummarizationPlugin()
        loader = AudioFileLoader()
        telemetry = InferenceTelemetry()
    }

    func run(
        wavURL: URL,
        quality: Quality = .fast,
        skipSummary: Bool = false,
        summaryModelId: String? = nil
    ) async throws -> PipelineResult {
        let totalStart = CFAbsoluteTimeGetCurrent()
        Term.info("Quality", "\(quality.rawValue) — \(quality.description)")

        // Load audio
        Term.progress("Loading audio...")
        let samples = try await loader.loadSamples(from: wavURL)
        let audioSeconds = Double(samples.count) / 16000.0
        Term.progressDone(CFAbsoluteTimeGetCurrent() - totalStart)
        Term.info("Duration", String(format: "%.1f min (%d samples)", audioSeconds / 60, samples.count))

        // Transcribe (pass 1)
        let (segment, txTime) = try await transcribeAudio(samples: samples, quality: quality)

        // Cleanup pass (high quality only)
        let (cleanupSegment, cleanupTime) = try await runCleanupPass(samples: samples, quality: quality)
        let finalTranscript = cleanupSegment ?? segment

        // Diarize
        let (speakers, dTime) = try await diarizeAudio(samples: samples)
        let diarized = SentenceAligner.align(transcript: finalTranscript, speakers: speakers, audioDuration: audioSeconds)
        Term.info("Aligned segments", "\(diarized.count) (from \(speakers.count) speaker segs)")

        // Summarize
        let (summaryResult, sTime, promptTokenCount, ctxWindow) = try await summarizeIfNeeded(
            diarized: diarized, skipSummary: skipSummary, summaryModelId: summaryModelId
        )

        let recentTelemetry = await telemetry.recentMetrics(limit: 5)
        for metric in recentTelemetry {
            Term.info("Telemetry [\(metric.modelId.rawValue)]", "RTF: \(String(format: "%.2f", metric.realTimeFactor)), Memory: \(metric.processMetrics?.processMemoryUsage ?? 0)MB, Faults: \(metric.processMetrics?.processPageFaults ?? 0)")
        }

        return PipelineResult(
            audioSeconds: audioSeconds,
            quality: quality,
            transcription: segment,
            transcriptionTime: txTime,
            cleanupTranscription: cleanupSegment,
            cleanupTime: cleanupTime,
            speakerSegments: speakers,
            diarizedSegments: diarized,
            diarizationTime: dTime,
            summary: summaryResult,
            summaryTime: sTime,
            promptTokens: promptTokenCount,
            contextWindow: ctxWindow,
            totalTime: CFAbsoluteTimeGetCurrent() - totalStart
        )
    }

    private func transcribeAudio(
        samples: [Float], quality: Quality
    ) async throws -> (TranscriptionSegment, TimeInterval) {
        var t = CFAbsoluteTimeGetCurrent()
        let segment: TranscriptionSegment
        let txTime: TimeInterval

        switch quality {
        case .fast, .high:
            Term.progress("Loading Parakeet model...")
            if !(await parakeet.isReady()) {
                try await parakeet.loadModel(ModelIDs.parakeetPrimary)
            }
            Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

            Term.progress("Transcribing (Parakeet)...")
            t = CFAbsoluteTimeGetCurrent()
            segment = try await parakeet.transcribe(
                samples: samples,
                context: TranscriptionContext(modelId: ModelIDs.parakeetPrimary, isFinalChunk: true)
            )
            txTime = CFAbsoluteTimeGetCurrent() - t
            Term.progressDone(txTime)

        case .max:
            Term.progress("Loading WhisperKit distil-large-v3...")
            if !(await whisper.isReady()) {
                try await whisper.loadModel(ModelIDs.cleanupTranscription)
            }
            Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

            Term.progress("Transcribing (WhisperKit distil-large-v3)...")
            t = CFAbsoluteTimeGetCurrent()
            segment = try await whisper.transcribe(
                samples: samples,
                context: TranscriptionContext(modelId: ModelIDs.cleanupTranscription, isFinalChunk: true)
            )
            txTime = CFAbsoluteTimeGetCurrent() - t
            Term.progressDone(txTime)
        }

        return (segment, txTime)
    }

    private func runCleanupPass(
        samples: [Float], quality: Quality
    ) async throws -> (TranscriptionSegment?, TimeInterval?) {
        guard quality == .high else { return (nil, nil) }

        Term.progress("Loading WhisperKit cleanup model...")
        var t = CFAbsoluteTimeGetCurrent()
        if !(await whisper.isReady()) {
            try await whisper.loadModel(ModelIDs.cleanupTranscription)
        }
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        Term.progress("Cleanup pass (WhisperKit distil-large-v3)...")
        t = CFAbsoluteTimeGetCurrent()
        let cleanupSegment = try await whisper.transcribe(
            samples: samples,
            context: TranscriptionContext(modelId: ModelIDs.cleanupTranscription, isFinalChunk: true)
        )
        let cleanupTime = CFAbsoluteTimeGetCurrent() - t
        Term.progressDone(cleanupTime)
        return (cleanupSegment, cleanupTime)
    }

    private func diarizeAudio(samples: [Float]) async throws -> ([SpeakerSegment], TimeInterval) {
        Term.progress("Loading diarization model...")
        var t = CFAbsoluteTimeGetCurrent()
        if !(await diarizer.isReady()) {
            try await diarizer.prepare()
        }
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        Term.progress("Diarizing speakers...")
        t = CFAbsoluteTimeGetCurrent()
        let speakers = try await diarizer.diarize(samples: samples, sampleRate: 16000)
        let dTime = CFAbsoluteTimeGetCurrent() - t
        Term.progressDone(dTime)
        return (speakers, dTime)
    }

    private func summarizeIfNeeded(
        diarized: [DiarizedSegment],
        skipSummary: Bool,
        summaryModelId: String?
    ) async throws -> (MeetingSummary?, TimeInterval?, Int?, Int?) {
        guard !skipSummary else { return (nil, nil, nil, nil) }

        let sumConfig = if let modelSlug = summaryModelId {
            SummaryConfig(
                modelId: ModelID(modelSlug),
                maxTokens: 2048,
                temperature: 0.3,
                enabled: true,
                meetingType: SummaryConfig.default.meetingType,
                contextWindow: 262_144
            )
        } else {
            SummaryConfig.default
        }
        Term.progress("Loading \(sumConfig.modelId.rawValue) for XGrammar...")
        var t = CFAbsoluteTimeGetCurrent()
        if !(await xgrammarSummarizer.isReady()) {
            try await xgrammarSummarizer.loadModel(sumConfig)
        }
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t)

        let text = diarized
            .map { "[\($0.speakerId)] \($0.text)" }
            .joined(separator: "\n")
        let speakerNames = Array(Set(diarized.map(\.speakerId))).map(\.rawValue)

        Term.progress("Summarizing meeting (XGrammar)...")
        let prompt = try await xgrammarSummarizer.buildPrompt(transcript: text, speakers: speakerNames, meetingType: sumConfig.meetingType)
        let promptTokenCount = await xgrammarSummarizer.countTokens(prompt)
        let ctxWindow = sumConfig.contextWindow
        let pctUsed = Double(promptTokenCount ?? 0) / Double(ctxWindow ?? 1) * 100
        Term.info("Tokens", "\(promptTokenCount ?? 0) prompt / \(ctxWindow ?? 0) context (\(String(format: "%.1f", pctUsed))% used)")

        t = CFAbsoluteTimeGetCurrent()
        do {
            let xgrammarResult = try await xgrammarSummarizer.summarize(transcript: text, speakers: speakerNames, meetingType: sumConfig.meetingType)
            let xgrammarTime = CFAbsoluteTimeGetCurrent() - t
            Term.progressDone(xgrammarTime)
            Term.info("XGrammar Time", "\(String(format: "%.2f", xgrammarTime))s")
            return (xgrammarResult, xgrammarTime, promptTokenCount, ctxWindow)
        } catch {
            let sTime = CFAbsoluteTimeGetCurrent() - t
            Term.progressDone(sTime)
            Term.error("Summary failed: \(error)")
            return (nil, sTime, promptTokenCount, ctxWindow)
        }
    }

    private func mergeSpeakers(
        transcript: TranscriptionSegment,
        speakers: [SpeakerSegment]
    ) -> [DiarizedSegment] {
        [transcript].map { seg in
            let best = speakers
                .map { (speaker: $0, overlap: overlap($0, seg)) }
                .max(by: { $0.overlap < $1.overlap })
            let sid: SpeakerID = if let b = best, b.overlap > 0 {
                b.speaker.speakerId
            } else {
                SpeakerID.unknown
            }
            return DiarizedSegment(
                text: seg.text, speakerId: sid,
                startTime: seg.startTime, endTime: seg.endTime,
                confidence: seg.confidence
            )
        }
    }

    private nonisolated func overlap(
        _ s: SpeakerSegment, _ t: TranscriptionSegment
    ) -> TimeInterval {
        max(0, min(s.endTime, t.endTime) - max(s.startTime, t.startTime))
    }
}
